const entry = $json.body.entry?.[0];
const change = entry?.changes?.[0]?.value;
const message = change?.messages?.[0];

if (!message) {
  return []; // Evento sin mensaje (ej. status de entrega) - se ignora
}

return [{
  json: {
    wa_id: message.from,
    texto: message.text?.body || '',
    phone_number_id: change.metadata?.phone_number_id,
    timestamp: message.timestamp
  }
}];

const clinic = $input.first().json;
const horario = clinic.horario_json;
const now = new Date(new Date().toLocaleString('en-US', { timeZone: 'Europe/Madrid' }));
const dias = ['domingo','lunes','martes','miercoles','jueves','viernes','sabado'];
const diaHoy = dias[now.getDay()];
const horarioHoy = horario[diaHoy];

let fueraDeHorario = true;
if (horarioHoy) {
  const [hA, mA] = horarioHoy.apertura.split(':').map(Number);
  const [hC, mC] = horarioHoy.cierre.split(':').map(Number);
  const minutosAhora = now.getHours() * 60 + now.getMinutes();
  const minutosApertura = hA * 60 + mA;
  const minutosCierre = hC * 60 + mC;
  fueraDeHorario = !(minutosAhora >= minutosApertura && minutosAhora < minutosCierre);
}

return [{ json: { ...clinic, fueraDeHorario } }];

