const FALLBACK = 'Gracias por tu mensaje. Hemos recibido tu consulta y te responderemos en cuanto abramos. Si es una urgencia, por favor llama al ' + ($json.telefono_urgencias || 'teléfono de la clínica') + '.';

try {
  const raw = $json.choices[0].message.content;
  const parsed = JSON.parse(raw);
  if (typeof parsed.respuesta !== 'string') throw new Error('formato inesperado');
  return [{ json: { respuesta: parsed.respuesta, es_urgencia: !!parsed.es_urgencia, fallback_usado: false } }];
} catch (err) {
  return [{ json: { respuesta: FALLBACK, es_urgencia: false, fallback_usado: true } }];
}
